class AntaresPanel final : public juce::Component,private juce::Timer {
    StudioMain& owner;juce::Label title,description,pluginLabel,status,keyParamLabel,scaleParamLabel,learning,values,targetLabel;juce::TextButton load{u("Nạp Antares VST3")},editor{u("Mở Antares")},scan{u("Tự nhận diện")},detect{u("Dò beat đã chọn → gửi")},captureNote{u("Học Key đang chọn")},captureMajor{u("Học Major")},captureMinor{u("Học Minor")},send{u("Gửi Key/Scale")};juce::ToggleButton automatic{u("Tự gửi sau dò / đổi tone bài")},bypass{u("Bypass plugin để đối chiếu / dùng chỉnh phô tích hợp")};juce::ComboBox keyParameter,scaleParameter,note,target,mode;std::vector<PluginControl> controls;juce::String identity;int lastTonic=-2;bool lastMinor=false;
    void populate(){controls.clear();keyParameter.clear(juce::dontSendNotification);scaleParameter.clear(juce::dontSendNotification);if(auto* plugin=owner.engine.pluginInstance()){controls=pluginToneControls(*plugin);for(std::size_t i=0;i<controls.size();++i){const auto label=controls[i].name+" ["+controls[i].id+"]";keyParameter.addItem(label,static_cast<int>(i)+1);scaleParameter.addItem(label,static_cast<int>(i)+1);if(controls[i].id==owner.engine.toneLink.keyId)keyParameter.setSelectedId(static_cast<int>(i)+1,juce::dontSendNotification);if(controls[i].id==owner.engine.toneLink.scaleId)scaleParameter.setSelectedId(static_cast<int>(i)+1,juce::dontSendNotification);}}}
    void capture(int which){auto* plugin=owner.engine.pluginInstance();if(!owner.canEdit()||!plugin)return;auto& link=owner.engine.toneLink;const int choice=(which<12?keyParameter:scaleParameter).getSelectedId()-1;if(!juce::isPositiveAndBelow(choice,static_cast<int>(controls.size())))return;const auto id=controls[static_cast<std::size_t>(choice)].id;for(const auto& c:pluginToneControls(*plugin))if(c.id==id){link.identity=pluginToneIdentity(*plugin);if(which<12){link.keyId=id;link.notes[static_cast<std::size_t>(which)]=c.value;}else{link.scaleId=id;(which==12?link.major:link.minor)=c.value;}owner.engine.toneLinkStatus=u("Đã học giá trị từ điều khiển bạn đang đặt trong Antares. Cần đủ 12 Key, Major và Minor, mỗi Key khác nhau.");owner.save();break;}}
    void timerCallback() override {auto* plugin=owner.engine.pluginInstance();const auto current=plugin?pluginToneIdentity(*plugin):juce::String{};if(current!=identity){identity=current;populate();}const bool editable=owner.canEdit(),has=plugin!=nullptr;load.setEnabled(editable);editor.setEnabled(has&&!owner.isBusy());scan.setEnabled(editable&&has);send.setEnabled(editable&&has&&owner.engine.toneLink.complete());captureNote.setEnabled(editable&&has);captureMajor.setEnabled(editable&&has);captureMinor.setEnabled(editable&&has);for(auto* c:std::initializer_list<juce::Component*>{&keyParameter,&scaleParameter,&note,&target,&mode,&automatic,&bypass})c->setEnabled(editable&&has);bool beat=false;if(juce::isPositiveAndBelow(owner.selected,static_cast<int>(owner.engine.getTracks().size())))beat=!owner.engine.getTracks()[static_cast<std::size_t>(owner.selected)]->vocal;detect.setEnabled(editable&&beat);automatic.setToggleState(owner.engine.toneLink.enabled,juce::dontSendNotification);bypass.setToggleState(owner.engine.isPluginBypassed(),juce::dontSendNotification);pluginLabel.setText(owner.engine.pluginName(),juce::dontSendNotification);status.setText(owner.engine.toneLinkStatus,juce::dontSendNotification);int learned=0;for(float value:owner.engine.toneLink.notes)if(value>=0&&value<=1)++learned;if(owner.engine.toneLink.major>=0)++learned;if(owner.engine.toneLink.minor>=0)++learned;values.setText(u("Đã ghép ")+juce::String(learned)+u("/14 giá trị · ")+(owner.engine.toneLink.complete()?u("Sẵn sàng gửi đúng nhãn Key/Scale"):u("Chưa đủ hoặc còn trùng giá trị; không tự gửi")),juce::dontSendNotification);if(owner.engine.songTonic!=lastTonic||owner.engine.songMinor!=lastMinor){lastTonic=owner.engine.songTonic;lastMinor=owner.engine.songMinor;if(lastTonic>=0)target.setSelectedId(lastTonic+1,juce::dontSendNotification);mode.setSelectedId(lastMinor?2:1,juce::dontSendNotification);}}
public:
    explicit AntaresPanel(StudioMain& o):owner(o){for(juce::Component* c:std::initializer_list<juce::Component*>{&title,&description,&pluginLabel,&status,&keyParamLabel,&scaleParamLabel,&learning,&values,&targetLabel,&load,&editor,&scan,&detect,&captureNote,&captureMajor,&captureMinor,&send,&automatic,&bypass,&keyParameter,&scaleParameter,&note,&target,&mode})addAndMakeVisible(c);title.setText(u("DÒ TONE → KEY / SCALE ANTARES"),juce::dontSendNotification);title.setFont(juce::Font(19,juce::Font::bold));description.setText(u("Nạp bản Antares VST3 bạn có giấy phép. Ứng dụng đọc nhãn Key/Scale, không đoán thứ tự giá trị. Dò beat hoặc đổi bài theo giọng bạn sẽ tự gửi tone khi đã ghép. Antares xử lý micro lúc bật Kiểm âm FX."),juce::dontSendNotification);description.setColour(juce::Label::textColourId,muted);pluginLabel.setColour(juce::Label::textColourId,teal);status.setColour(juce::Label::textColourId,teal);status.setJustificationType(juce::Justification::topLeft);keyParamLabel.setText(u("Tham số Key / Root"),juce::dontSendNotification);scaleParamLabel.setText(u("Tham số Scale / Mode"),juce::dontSendNotification);learning.setText(u("Nếu chưa tự nhận diện: chọn đúng hai tham số bên trên. Mở Antares, đặt từng Key C…B rồi bấm Học Key tương ứng. Đặt Major / Minor trong plugin và học mỗi giá trị. Nếu plugin không công khai hai tham số, không thể gửi từ host."),juce::dontSendNotification);learning.setColour(juce::Label::textColourId,muted);values.setColour(juce::Label::textColourId,teal);targetLabel.setText(u("Tone bài đầu ra / chọn tay khi dò chưa rõ"),juce::dontSendNotification);for(int i=0;i<12;++i){note.addItem(vocal::noteName(60+i),i+1);target.addItem(vocal::noteName(60+i),i+1);}note.setSelectedId(1);target.setSelectedId(1);mode.addItem("Major",1);mode.addItem("Natural Minor",2);mode.setSelectedId(1);keyParameter.setTextWhenNothingSelected(u("Chọn tham số Key của plugin"));scaleParameter.setTextWhenNothingSelected(u("Chọn tham số Scale của plugin"));
        load.onClick=[this]{if(!owner.canEdit())return;owner.chooseAntaresPlugin();};editor.onClick=[this]{if(!owner.canEdit())return;owner.openAntaresEditor();};scan.onClick=[this]{if(!owner.canEdit())return;owner.engine.scanToneLink();populate();owner.save();};detect.onClick=[this]{if(!owner.canEdit())return;owner.analyseSelected();};automatic.onClick=[this]{if(!owner.canEdit())return;owner.engine.toneLink.enabled=automatic.getToggleState();owner.save();};bypass.onClick=[this]{if(!owner.canEdit())return;owner.engine.setPluginBypassed(bypass.getToggleState());owner.save();};keyParameter.onChange=[this]{if(!owner.canEdit())return;const int i=keyParameter.getSelectedId()-1;if(juce::isPositiveAndBelow(i,static_cast<int>(controls.size()))){owner.engine.toneLink.keyId=controls[static_cast<std::size_t>(i)].id;owner.engine.toneLink.notes.fill(-1);}};scaleParameter.onChange=[this]{if(!owner.canEdit())return;const int i=scaleParameter.getSelectedId()-1;if(juce::isPositiveAndBelow(i,static_cast<int>(controls.size()))){owner.engine.toneLink.scaleId=controls[static_cast<std::size_t>(i)].id;owner.engine.toneLink.major=owner.engine.toneLink.minor=-1;}};captureNote.onClick=[this]{if(!owner.canEdit())return;capture(note.getSelectedId()-1);};captureMajor.onClick=[this]{if(!owner.canEdit())return;capture(12);};captureMinor.onClick=[this]{if(!owner.canEdit())return;capture(13);};send.onClick=[this]{if(!owner.canEdit())return;owner.engine.songTonic=target.getSelectedId()-1;owner.engine.songMinor=mode.getSelectedId()==2;owner.engine.songKeySource=u("Chọn tay");owner.engine.sendSongKey();owner.save();};timerCallback();startTimerHz(10);}
    void resized() override {const int w=getWidth(),half=w/2;title.setBounds(20,12,w-40,30);description.setBounds(20,49,w-40,60);pluginLabel.setBounds(20,113,w-40,25);load.setBounds(22,148,180,32);editor.setBounds(215,148,150,32);scan.setBounds(378,148,160,32);detect.setBounds(w-272,148,250,32);automatic.setBounds(22,192,w-44,26);bypass.setBounds(22,225,w-44,26);status.setBounds(20,266,w-40,62);keyParamLabel.setBounds(22,335,half-44,22);scaleParamLabel.setBounds(half+8,335,half-30,22);keyParameter.setBounds(22,361,half-44,29);scaleParameter.setBounds(half+8,361,half-30,29);learning.setBounds(20,402,w-40,60);note.setBounds(22,474,100,29);captureNote.setBounds(135,474,210,30);captureMajor.setBounds(half+8,474,170,30);captureMinor.setBounds(half+190,474,170,30);values.setBounds(20,517,w-40,26);targetLabel.setBounds(22,559,w-44,25);target.setBounds(22,591,110,30);mode.setBounds(145,591,185,30);send.setBounds(345,591,190,30);}
    void paint(juce::Graphics& g) override {g.fillAll(bg);g.setColour(muted);g.setFont(12);g.drawText(u("Chỉ dùng một bộ chỉnh phô tại một thời điểm. Bypass Antares trước khi dùng chỉnh phô ngoại tuyến tích hợp."),20,getHeight()-52,getWidth()-40,34,juce::Justification::centredLeft);}
};
